export enum Seasons {
    SPRING = 0,
    SUMMER = 1,
    AUTUMN = 2,
    WINTER = 3,
    ALL_YEAR= 4
}

enum Period {
    MONTH,
    YEAR,
    DECADE,
    DECADES,
    IMMORTAL
}

enum PatternId {
    solid,
    spotted,
    dotted,
    mixed
}

