type PlantLifespan = {
    label: string
    period: Period,
    diesBySeason: boolean
    seasonToDie: Seasons | null
}

type FlowerColor = {
    label: string
    patternId: PatternId
    mainColor: string[]
    patternColor: string[]
}

type Flower = {
    label: string
    flowerColor: FlowerColor
}

type Color = {
    label: string
    patternId: PatternId
    mainColor: string[] | string
}

type CareItem = {
    label: string
    description?: string
    problems?: string
    solving?: string
}

type PlantCare = {
    label: string
    watering: CareItem
    light: CareItem
    humidity: CareItem
    soil: CareItem
    commonProblems: CareItem
    temperature: CareItem
    repotting: CareItem
    nutritious: string
}

type PlantGenderData  = {
    name: string
    tags: number[]
    size: [number, number]
    plantLifespan: PlantLifespan
    plantingTime: Seasons
    flower: Flower
    color: Color
    plantCare: PlantCare
}

type Pollination = {
    id: number
    label: string
    description: string
}


type Gender<T> = {
    male: T
    female: T
}

export type Catalog = {
    id: number
    rating: number
    label: string
    category: number[]
    genders: Gender<PlantGenderData >
    pollination: Pollination
}



